create or replace function public.reserve_offer_inventory_atomic(p_offer_id uuid,p_equipment_id uuid,p_reserved_qty numeric) returns table(ok boolean,reserved_qty numeric,available_qty numeric,message text) language plpgsql security definer set search_path=public,pg_temp as $$ declare v_available numeric; v_other_reserved numeric; v_item_id uuid; v_status text; begin if p_reserved_qty is null or p_reserved_qty < 0 then return query select false,0::numeric,0::numeric,'Geçerli rezerv miktarı gerekli.'; return; end if; select status into v_status from public.teklifler where id=p_offer_id for update; if not found then return query select false,0::numeric,0::numeric,'Teklif bulunamadı.'; return; end if; select available_quantity into v_available from public.equipment where id=p_equipment_id and active=true for update; if not found then return query select false,0::numeric,0::numeric,'Ekipman bulunamadı.'; return; end if; select id into v_item_id from public.offer_items where offer_id=p_offer_id and equipment_id=p_equipment_id limit 1 for update; if not found then return query select false,0::numeric,v_available,'Teklif kaleminde bu ekipman yok.'; return; end if; select coalesce(sum(oi.inventory_reserved_qty),0) into v_other_reserved from public.offer_items oi join public.teklifler t on t.id=oi.offer_id where oi.equipment_id=p_equipment_id and oi.offer_id<>p_offer_id and coalesce(oi.inventory_reserved_qty,0)>0 and t.status not in ('rejected','archived','cancelled'); if p_reserved_qty + v_other_reserved > v_available then return query select false,0::numeric,greatest(v_available-v_other_reserved,0),'Yetersiz stok.'; return; end if; update public.offer_items set inventory_reserved_qty=p_reserved_qty,inventory_available_qty=greatest(v_available-v_other_reserved,0) where id=v_item_id; return query select true,p_reserved_qty,greatest(v_available-v_other_reserved,0),'OK'; end; $$; revoke all on function public.reserve_offer_inventory_atomic(uuid,uuid,numeric) from public,anon,authenticated; grant execute on function public.reserve_offer_inventory_atomic(uuid,uuid,numeric) to service_role;